"""Disposable client worlds: a flat template generated by the pinned vanilla server, and data packs.

The template is generated once per server jar SHA-1 and settings, by the official server of the
same version, and reused from the cache only while its level.dat still matches the recorded hash.
Each run copies it into the client's own saves folder and adds the scenario's data pack. A copy
that the harness sprints through allows commands (the template, from a dedicated server, does not).
"""

from __future__ import annotations

import gzip
import hashlib
import json
import shutil
import time
from pathlib import Path
from typing import Any, Callable

from ..acquire import AcquisitionError, contained, hash_file
from ..platforms import DONE_RE
from ..procs import ProcessRegistry, allocate_port

TEMPLATE_WORLD = "world"
WORLD_PROPERTIES = {
    "server-ip": "127.0.0.1", "online-mode": "false", "enable-rcon": "false", "enable-query": "false",
    "level-type": "minecraft\\:flat", "level-seed": "egc-compat", "generate-structures": "false",
    "difficulty": "easy", "gamemode": "creative", "spawn-protection": "0", "view-distance": "4",
    "simulation-distance": "4", "max-players": "1", "motd": "egc-client-worldgen", "pause-when-empty-seconds": "-1",
}
# Windows MAX_PATH applies to the nested data-pack files, so pack folders stay short.
MAX_PACK_PATH = 250
# level.dat's Data.allowCommands: NBT byte tag (type 1), name length 13, name, then the value.
ALLOW_COMMANDS_TAG = b"\x01\x00\x0dallowCommands"


def settings_key() -> str:
    return hashlib.sha256(json.dumps(WORLD_PROPERTIES, sort_keys=True).encode("utf-8")).hexdigest()[:8]


def template(cache_dir: Path, minecraft: str, server_jar: Path, server_sha1: str, registry: ProcessRegistry,
             java: str, deadline: float, say: Callable[[str], None]) -> tuple[Path, dict[str, Any]]:
    """The template world folder and its record, generating it on first use."""
    folder = contained(cache_dir, "client", "worlds", f"{minecraft}-{server_sha1[:12]}-{settings_key()}")
    record_path = folder / "template.json"
    if record_path.is_file():
        record = json.loads(record_path.read_text(encoding="utf-8"))
        if hash_file(folder / TEMPLATE_WORLD / "level.dat") == record.get("level_dat_sha256"):
            return folder / TEMPLATE_WORLD, {**record, "from_cache": True}
        shutil.rmtree(folder)  # changed since it was recorded: regenerate
    say(f"generating the {minecraft} world template with the pinned vanilla server")
    work = contained(cache_dir, "client", "worldgen", f"{minecraft}-{server_sha1[:12]}")
    shutil.rmtree(work, ignore_errors=True)
    work.mkdir(parents=True)
    (work / "eula.txt").write_text("eula=true\n", encoding="utf-8")
    properties = {**WORLD_PROPERTIES, "server-port": allocate_port()}
    (work / "server.properties").write_text("".join(f"{k}={v}\n" for k, v in properties.items()), encoding="utf-8")
    log = work / "worldgen.log"
    server = registry.start(f"worldgen-{minecraft}", [java, "-Xmx1G", "-jar", str(server_jar), "--nogui"], work, log)
    done = server.output.wait_for(DONE_RE, 0, max(1.0, min(240.0, deadline - time.monotonic())),
                                  abort=lambda: not server.running())
    if done is None:
        server.kill()
        server.close_streams()
        raise AcquisitionError(f"{minecraft} world generation did not reach Done", "download")
    banner = next((line.text for line in server.output.lines() if "Starting minecraft server version" in line.text), None)
    server.send_line("stop")
    code = server.wait(120)
    server.close_streams()
    if code != 0:
        raise AcquisitionError(f"{minecraft} world generation server exited {code}", "download")
    staging = folder.with_name(folder.name + ".staging")
    shutil.rmtree(staging, ignore_errors=True)
    shutil.copytree(work / TEMPLATE_WORLD, staging / TEMPLATE_WORLD)
    shutil.copy2(log, staging / "worldgen.log")
    record = {"minecraft": minecraft, "server_sha1": server_sha1, "banner": banner, "exit_code": code,
              "level_dat_sha256": hash_file(staging / TEMPLATE_WORLD / "level.dat"), "properties": properties,
              "generated_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())}
    (staging / "template.json").write_text(json.dumps(record, indent=2) + "\n", encoding="utf-8")
    staging.rename(folder)
    shutil.rmtree(work, ignore_errors=True)
    return folder / TEMPLATE_WORLD, {**record, "from_cache": False}


def install_world(template_world: Path, saves: Path, name: str) -> Path:
    destination = contained(saves, name)
    shutil.copytree(template_world, destination)
    return destination


def allow_commands(world: Path) -> dict[str, str]:
    """Set ``Data.allowCommands`` in an installed copy's level.dat, so its player may run ``/tick``.

    The byte is patched in place in the decompressed NBT; the file must hold exactly one such tag.
    Returns the level.dat SHA-256 before and after.
    """
    path = world / "level.dat"
    before = hash_file(path)
    data = bytearray(gzip.decompress(path.read_bytes()))
    if data.count(ALLOW_COMMANDS_TAG) != 1:
        raise ValueError(f"{path} does not hold exactly one allowCommands tag")
    data[data.index(ALLOW_COMMANDS_TAG) + len(ALLOW_COMMANDS_TAG)] = 1
    path.write_bytes(gzip.compress(bytes(data), mtime=0))
    return {"level_dat_before": before, "level_dat_after": hash_file(path)}


def pack_file(world: Path, folder: str, function: str) -> Path:
    return world / "datapacks" / folder / "data" / "egc" / "function" / f"{function}.mcfunction"


def path_problem(path: Path) -> str | None:
    """Why ``path`` is too deep to write on Windows, or None."""
    if len(str(path)) <= MAX_PACK_PATH:
        return None
    return (f"run directory too deep for Windows paths: {path} is {len(str(path))} characters, over the "
            f"{MAX_PACK_PATH} allowed; use a shorter --out")


def pack_mcmeta(pack_version: dict[str, Any], description: str) -> dict[str, Any]:
    """``pack_format`` before 1.21.9; from 1.21.9 the exact ``min_format``/``max_format`` pair."""
    if "data" in pack_version:
        return {"pack": {"pack_format": pack_version["data"], "description": description}}
    exact = [pack_version["data_major"], pack_version.get("data_minor", 0)]
    return {"pack": {"min_format": exact, "max_format": exact, "description": description}}


def write_pack(world: Path, folder: str, functions: dict[str, list[str]], pack_version: dict[str, Any],
               description: str) -> dict[str, str]:
    """Write a data pack whose load/tick tags call ``<namespace>:load`` and ``:tick``; return file hashes."""
    root = world / "datapacks" / folder
    problem = path_problem(pack_file(world, folder, max(functions, key=len)))
    if problem:
        raise AcquisitionError(problem, "unsafe_path")
    files = {"pack.mcmeta": json.dumps(pack_mcmeta(pack_version, description), indent=2) + "\n",
             "data/minecraft/tags/function/load.json": json.dumps({"values": ["egc:load"]}) + "\n",
             "data/minecraft/tags/function/tick.json": json.dumps({"values": ["egc:tick"]}) + "\n"}
    for name, lines in functions.items():
        files[f"data/egc/function/{name}.mcfunction"] = "\n".join(lines) + "\n"
    hashes = {}
    for relative, text in files.items():
        path = root / relative
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8", newline="\n")
        hashes[relative] = hashlib.sha256(text.encode("utf-8")).hexdigest()
    return hashes
